//! 📐️ Typed uninitialized array storage admits each scalar and field store without any N-element callback at birth or publication.
use super::*;
use std::mem::MaybeUninit;
pub struct ArrayReceiving<T:OwnedScalar+Copy,const N:usize>{source:OwnedSlot<FieldValue>,current:OwnedSlot<FieldValue>,output:OwnedSlot<[T;N]>,rows:ManuallyDrop<MaybeUninit<[T;N]>>,pending:Option<T>,live:usize,index:usize,phase:u8,closing:bool,failed:bool}
impl<T:OwnedScalar+Copy,const N:usize>Default for ArrayReceiving<T,N>{fn default()->Self{Self{source:Default::default(),current:Default::default(),output:Default::default(),rows:ManuallyDrop::new(MaybeUninit::uninit()),pending:None,live:0,index:0,phase:0,closing:false,failed:false}}}
impl<T:OwnedScalar+Copy,const N:usize>DslOwnedReceivingField for[T;N]{type Cursor=ArrayReceiving<T,N>;fn receiving_cursor()->Self::Cursor{Self::Cursor::default()}}
impl<T:OwnedScalar+Copy,const N:usize>ArrayReceiving<T,N>{
 fn selected(&mut self,source:&mut Option<FieldValue>,body:usize,effect:&mut RetainedAllocationEffect<'_>)->OwnedPoll{
  if self.closing||self.failed{return done(effect,Err(invariant().into()))}if self.phase==6{return idle(effect)}
  let d=match self.demands(source,body){Ok(d)=>d,Err(error)=>return done(effect,Err(error.into()))};if !admits(effect,d){return idle(effect)}
  if self.phase==5&&!self.source.terminal_is_empty(){let poll=self.source.close_step(effect);return settle(effect,receiving(poll))}
  local(effect,d,||{match self.phase{0=>{if !matches!(source.as_ref(),Some(FieldValue::Tuple(v))if v.len()==N){return Err(invalid())}*self.source.value=source.take();self.phase=1;},1=>{if self.index==N{self.phase=4;}else{let Some(FieldValue::Tuple(v))=self.source.value.as_mut()else{return Err(invariant())};if !self.current.terminal_is_empty(){return Err(invariant())}*self.current.value=Some(std::mem::replace(v.get_mut(self.index).ok_or_else(invariant)?,FieldValue::Absent));self.phase=2;}},2=>{self.pending=Some(T::take_source(&mut self.current.value)?);self.phase=3;},3=>{if self.index!=self.live||self.live>=N{return Err(invariant())}let value=self.pending.take().ok_or_else(invariant)?;unsafe{self.rows.as_mut_ptr().cast::<T>().add(self.live).write(value)}self.live+=1;self.index+=1;self.phase=1;},4=>{if self.live!=N{return Err(invariant())}*self.output.value=Some(unsafe{self.rows.as_ptr().read()});self.live=0;self.phase=5;},5=>self.phase=6,_=>return Err(invariant())}Ok(())})
 }
}
impl<T:OwnedScalar+Copy,const N:usize>OwnedFieldReceiving<[T;N]>for ArrayReceiving<T,N>{
 fn demands(&self,_:&Option<FieldValue>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.failed{return Err(invariant())}match self.phase{2=>Ok(RetirementDemand{copy_bytes:T::creation_bytes(),depth:1,..Default::default()}),3=>Ok(payload::<T>()),5 if !self.source.terminal_is_empty()=>self.source.close_demands(body),6=>Ok(Default::default()),_=>Ok(metadata::<()>())}}
 fn select_advance(&self,_:&Option<FieldValue>,body:usize,_:u64)->Result<OwnedAdvanceSelection,ValueError>{if self.closing||self.failed{return Err(invariant())}Ok(OwnedAdvanceSelection::Local{work:match self.phase{5 if !self.source.terminal_is_empty()=>self.source.close_work_demand(body)?,6=>0,_=>1}})}
 fn advance_local(&mut self,source:&mut Option<FieldValue>,body:usize,effect:&mut RetainedAllocationEffect<'_>)->OwnedPoll{let poll=self.selected(source,body,effect);poison(&mut self.failed,&poll);poll}
 fn is_ready(&self)->bool{!self.closing&&!self.failed&&self.phase==6&&self.output.value.is_some()}
 fn take_into(&mut self,output:&mut Option<[T;N]>,effect:&mut RetainedAllocationEffect<'_>)->OwnedTake{if !self.is_ready(){return done(effect,Err(invariant()))}move_into(&mut self.output.value,output,effect)}
 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.terminal_is_empty(){return Ok(Default::default())}if !self.closing{return Ok(metadata::<()>())}if !self.current.terminal_is_empty(){return self.current.close_demands(body)}if self.pending.is_some()||self.live>0{return Ok(metadata::<()>())}if !self.output.terminal_is_empty(){return self.output.close_demands(body)}self.source.close_demands(body)}
 fn close_work_demand(&self,body:usize)->Result<u64,ValueError>{if self.terminal_is_empty(){return Ok(0)}if !self.closing||self.pending.is_some()||self.live>0{return Ok(1)}if !self.current.terminal_is_empty(){return self.current.close_work_demand(body)}if !self.output.terminal_is_empty(){return self.output.close_work_demand(body)}self.source.close_work_demand(body)}
 fn close_step(&mut self,effect:&mut RetainedAllocationEffect<'_>)->OwnedClose{if self.terminal_is_empty(){return idle(effect)}let d=match self.close_demands(effect.grant().maximum_copy_bytes){Ok(d)=>d,Err(error)=>return done(effect,Err(error.into()))};if !admits(effect,d){return idle(effect)}if !self.closing{return local_close(effect,d,||{self.closing=true;Ok(())})}if !self.current.terminal_is_empty(){return self.current.close_step(effect)}if self.pending.is_some(){return local_close(effect,d,||{self.pending=None;Ok(())})}if self.live>0{return local_close(effect,d,||{self.live-=1;Ok(())})}if !self.output.terminal_is_empty(){return self.output.close_step(effect)}self.source.close_step(effect)}
 fn terminal_is_empty(&self)->bool{self.current.terminal_is_empty()&&self.pending.is_none()&&self.live==0&&self.output.terminal_is_empty()&&self.source.terminal_is_empty()}
}
impl<T:OwnedScalar+Copy,const N:usize>Drop for ArrayReceiving<T,N>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"owned fixed array requires paid terminal closure");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.rows)}}}}
